import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, GeoJSON, useMapEvents, Polygon } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

const API_BASE = "http://localhost:8000";

// --- Thành phần xử lý sự kiện Click để vẽ Polygon ---
function MapEvents({ drawingMode, currentPoints, setCurrentPoints }) {
    useMapEvents({
        click(e) {
            if (drawingMode) {
                const { lat, lng } = e.latlng;
                setCurrentPoints([...currentPoints, [lat, lng]]);
            }
        },
    });
    return null;
}

export default function AdminDashboard() {
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState("territories");
    const [territories, setTerritories] = useState([]);
    const [allZones, setAllZones] = useState([]);
    const [statistics, setStatistics] = useState({});

    // States cho quản lý Phân vùng
    const [selectedTerritoryId, setSelectedTerritoryId] = useState(null);
    const [showTerritoryForm, setShowTerritoryForm] = useState(false);
    const [newTerritoryName, setNewTerritoryName] = useState("");
    
    // States cho việc vẽ/chỉnh sửa Zone
    const [isDrawing, setIsDrawing] = useState(false);
    const [editingZoneId, setEditingZoneId] = useState(null); // Lưu ID zone đang được cập nhật vị trí
    const [tempPoints, setTempPoints] = useState([]); 
    const [newZoneName, setNewZoneName] = useState("");

    // Sales States
    const [allSales, setAllSales] = useState([]);
    const [pendingSales, setPendingSales] = useState([]);

    useEffect(() => {
        fetchInitialData();
        fetchTerritories();
        fetchSalesData();
    }, []);

    const fetchInitialData = async () => {
        try {
            const sRes = await fetch(`${API_BASE}/admin/statistics`);
            if (sRes.ok) setStatistics(await sRes.json());
            const zRes = await fetch(`${API_BASE}/zones`);
            if (zRes.ok) setAllZones(await zRes.json());
        } catch (e) { console.error("Error stats:", e); }
    };

    const fetchTerritories = async () => {
        try {
            const res = await fetch(`${API_BASE}/territories`);
            if (res.ok) setTerritories(await res.json());
        } catch (e) { console.error("Error territories:", e); }
    };

    const fetchSalesData = async () => {
        try {
            const [pRes, aRes] = await Promise.all([
                fetch(`${API_BASE}/admin/pending-sales`),
                fetch(`${API_BASE}/admin/all-sales`)
            ]);
            if (pRes.ok) setPendingSales(await pRes.json());
            if (aRes.ok) setAllSales(await aRes.json());
        } catch (e) { console.error("Error sales:", e); }
    };

    // --- Xử lý Territory ---
    const handleCreateTerritory = async () => {
        if (!newTerritoryName) return alert("Nhập tên phân vùng");
        try {
            const res = await fetch(`${API_BASE}/territories`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: newTerritoryName, zone_ids: [] })
            });
            if (res.ok) {
                setNewTerritoryName("");
                setShowTerritoryForm(false);
                fetchTerritories();
            }
        } catch (e) { alert("Lỗi kết nối API"); }
    };

    const handleDeleteTerritory = async (id) => {
        if (!window.confirm("Xóa phân vùng này?")) return;
        try {
            await fetch(`${API_BASE}/territories/${id}`, { method: "DELETE" });
            fetchTerritories();
            setSelectedTerritoryId(null);
        } catch (e) { alert("Lỗi khi xóa"); }
    };

    // --- Xử lý Vẽ & Hoàn tác ---
    const startDrawing = () => {
        if (!selectedTerritoryId) return alert("Vui lòng chọn Phân vùng trước");
        setIsDrawing(true);
        setEditingZoneId(null);
        setTempPoints([]);
        setNewZoneName("");
    };

    const undoLastPoint = () => {
        setTempPoints(prev => prev.slice(0, -1));
    };

    // Chuẩn bị cập nhật vị trí cho Zone cũ
    const prepareUpdateLocation = (zone) => {
        setIsDrawing(true);
        setEditingZoneId(zone.id);
        setNewZoneName(zone.name);
        setTempPoints([]); // Yêu cầu vẽ lại từ đầu
        alert(`Đang cập nhật vị trí cho vùng: ${zone.name}. Hãy click các điểm mới trên bản đồ.`);
    };

    const saveDrawnZone = async () => {
        if (tempPoints.length < 3) return alert("Cần ít nhất 3 điểm để tạo một vùng");
        if (!newZoneName) return alert("Vui lòng nhập tên vùng");

        const coords = [...tempPoints, tempPoints[0]].map(p => [p[1], p[0]]); 
        const geometry = { type: "Polygon", coordinates: [coords] };

        const zoneData = {
            name: newZoneName,
            geometry: geometry,
            center_lat: tempPoints[0][0],
            center_lng: tempPoints[0][1]
        };

        try {
            if (editingZoneId) {
                // CẬP NHẬT ZONE CŨ
                await fetch(`${API_BASE}/zones/${editingZoneId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(zoneData)
                });
                alert("Cập nhật vị trí thành công!");
            } else {
                // TẠO ZONE MỚI
                const res = await fetch(`${API_BASE}/zones`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ ...zoneData, zone_code: `Z-${Date.now()}`, district_id: 1 })
                });
                const createdZone = await res.json();
                if (res.ok) {
                    const territory = territories.find(t => t.id === selectedTerritoryId);
                    const updatedZoneIds = [...(territory.zone_ids || []), createdZone.id];
                    await fetch(`${API_BASE}/territories/${selectedTerritoryId}`, {
                        method: "PUT",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ name: territory.name, zone_ids: updatedZoneIds })
                    });
                }
            }
            setIsDrawing(false);
            setTempPoints([]);
            setEditingZoneId(null);
            setNewZoneName("");
            fetchInitialData();
            fetchTerritories();
        } catch (e) { alert("Lỗi khi lưu dữ liệu"); }
    };

    const handleUpdateZoneName = async (zoneId, newName) => {
        if (!newName) return;
        try {
            await fetch(`${API_BASE}/zones/${zoneId}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: newName })
            });
            fetchInitialData();
        } catch (e) { console.error("Update name error"); }
    };

    const deleteZone = async (zoneId) => {
        if (!window.confirm("Xóa vùng này khỏi hệ thống?")) return;
        try {
            await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
            fetchInitialData();
            fetchTerritories();
        } catch (e) { alert("Lỗi khi xóa"); }
    };

    // Lọc các Zone thuộc Phân vùng đang chọn
    const activeZones = useMemo(() => {
        const territory = territories.find(t => t.id === selectedTerritoryId);
        if (!territory || !territory.zone_ids) return [];
        return allZones.filter(z => territory.zone_ids.includes(z.id));
    }, [selectedTerritoryId, territories, allZones]);

    const getZoneColor = (index) => {
        const colors = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#1abc9c', '#e67e22', '#34495e'];
        return colors[index % colors.length];
    };

    return (
        <div className="admin-container">
            <aside className="admin-sidebar">
                <div className="logo">🚀 Territory System</div>
                <nav className="main-nav">
                    <button className={activeTab === "dashboard" ? "active" : ""} onClick={() => setActiveTab("dashboard")}>📊 Dashboard</button>
                    <button className={activeTab === "territories" ? "active" : ""} onClick={() => setActiveTab("territories")}>🗺️ Quản lý Phân vùng</button>
                    <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>👥 Nhân viên Sales</button>
                </nav>
                <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
            </aside>

            <main className="admin-main">
                {activeTab === "territories" && (
                    <div className="tab-content">
                        <div className="zone-mgr-header">
                            <h2>🗺️ Thiết kế Phân vùng</h2>
                            <button className="btn-primary" onClick={() => setShowTerritoryForm(true)}>➕ Tạo Phân vùng mới</button>
                        </div>

                        <div className="zone-mgr-layout">
                            <div className="district-list">
                                <h4>Phân vùng hiện có</h4>
                                {territories.map(t => (
                                    <div key={t.id} className={`dist-item-wrapper ${selectedTerritoryId === t.id ? "active" : ""}`}>
                                        <div className="dist-item" onClick={() => setSelectedTerritoryId(t.id)}>
                                            📍 {t.name}
                                        </div>
                                        <button className="btn-small-del" onClick={() => handleDeleteTerritory(t.id)}>🗑️</button>
                                    </div>
                                ))}
                            </div>

                            <div className="zone-display">
                                <div className="map-toolbar">
                                    {isDrawing ? (
                                        <div className="drawing-controls">
                                            <input 
                                                type="text" 
                                                placeholder="Tên vùng..." 
                                                value={newZoneName} 
                                                onChange={e => setNewZoneName(e.target.value)} 
                                            />
                                            <button className="btn-success" onClick={saveDrawnZone}>💾 Lưu {editingZoneId ? "vị trí mới" : "vùng mới"}</button>
                                            <button className="btn-draw" onClick={undoLastPoint}>↩️ Hoàn tác điểm</button>
                                            <button className="btn-reject" onClick={() => { setIsDrawing(false); setTempPoints([]); setEditingZoneId(null); }}>🚫 Hủy</button>
                                        </div>
                                    ) : (
                                        <button className="btn-draw" onClick={startDrawing} disabled={!selectedTerritoryId}>
                                            ✏️ Vẽ thêm vùng mới (Zone)
                                        </button>
                                    )}
                                </div>

                                <div className="map-box">
                                    <MapContainer center={[21.0285, 105.8542]} zoom={13} style={{ height: '450px', width: '100%' }}>
                                        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                        <MapEvents drawingMode={isDrawing} currentPoints={tempPoints} setCurrentPoints={setTempPoints} />

                                        {/* Vẽ các điểm đang vẽ dở */}
                                        {tempPoints.length > 0 && (
                                            <Polygon positions={tempPoints} pathOptions={{ color: 'orange', dashArray: '5, 5' }} />
                                        )}

                                        {/* Tự động vẽ tất cả các Zone hiện có của phân vùng */}
                                        {activeZones.map((z, idx) => (
                                            <GeoJSON 
                                                key={`${z.id}-${JSON.stringify(z.geometry)}`} // Thêm key unique để render lại khi geometry đổi
                                                data={z.geometry} 
                                                style={{ color: getZoneColor(idx), fillOpacity: 0.4, weight: 3 }}
                                            >
                                                <Popup>
                                                    <strong>Vùng: {z.name}</strong>
                                                </Popup>
                                            </GeoJSON>
                                        ))}
                                    </MapContainer>
                                </div>
                                
                                {/* DANH SÁCH CHI TIẾT ZONES VÀ QUẢN LÝ */}
                                <div className="zone-management-panel">
                                    <h4>Danh sách chi tiết các vùng thuộc Phân vùng này:</h4>
                                    {activeZones.length > 0 ? (
                                        <table className="zone-table">
                                            <thead>
                                                <tr>
                                                    <th>Màu</th>
                                                    <th>Tên Zone (Click để sửa)</th>
                                                    <th>Hành động</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {activeZones.map((z, idx) => (
                                                    <tr key={z.id}>
                                                        <td><div className="color-indicator" style={{backgroundColor: getZoneColor(idx)}}></div></td>
                                                        <td>
                                                            <input 
                                                                type="text" 
                                                                defaultValue={z.name} 
                                                                onBlur={(e) => handleUpdateZoneName(z.id, e.target.value)}
                                                                className="inline-edit-input"
                                                            />
                                                        </td>
                                                        <td>
                                                            <button className="btn-edit-loc" onClick={() => prepareUpdateLocation(z)}>📍 Vẽ lại vị trí</button>
                                                            <button className="btn-small-del" onClick={() => deleteZone(z.id)}>🗑️ Xóa</button>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    ) : (
                                        <p className="no-data-msg">Chưa có vùng nào. Hãy nhấn "Vẽ thêm vùng mới" để bắt đầu.</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === "dashboard" && (
                    <div className="tab-content">
                        <h2>Tổng quan hệ thống</h2>
                        <div className="stats-grid">
                            <div className="stat-card"><h3>{allZones.length}</h3><p>Tổng số Zones</p></div>
                            <div className="stat-card"><h3>{territories.length}</h3><p>Tổng số Phân vùng</p></div>
                        </div>
                    </div>
                )}
            </main>

            {showTerritoryForm && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Tạo Phân vùng mới</h3>
                        <input type="text" placeholder="Tên phân vùng..." value={newTerritoryName} onChange={e => setNewTerritoryName(e.target.value)} />
                        <div className="modal-btns">
                            <button className="btn-success" onClick={handleCreateTerritory}>Tạo</button>
                            <button onClick={() => setShowTerritoryForm(false)}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
